<?php
declare(strict_types=1);

require_once __DIR__ . '/../../auth/require_role.php';
requireRole(['student']);

require_once __DIR__ . '/../../config/database.php';

date_default_timezone_set('Asia/Manila');

function redirectToPermit(string $error = ''): void
{
    $parameters = ['page' => 'permit-application'];

    if ($error !== '') {
        $parameters['error'] = $error;
    }

    header('Location: dashboard.php?' . http_build_query($parameters), true, 303);
    exit;
}

/*
 * Only remove files generated by this upload handler. A legacy filename
 * with an unfamiliar format is left in storage for manual inspection.
 */
function removeStoredPermitFile(string $directory, string $filename): void
{
    if (!preg_match('/\A[a-f0-9]{48}\.(?:pdf|jpg|png)\z/', $filename)) {
        return;
    }

    $path = $directory . '/' . $filename;

    if (is_file($path) && !@unlink($path)) {
        error_log('AcadTrack: Could not remove permit file ' . $filename);
    }
}

/*
|--------------------------------------------------------------------------
| VALIDATE REQUEST AND PAYMENT
|--------------------------------------------------------------------------
*/

if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    redirectToPermit('invalid_request');
}

$studentId = (int) ($_SESSION['user_id'] ?? 0);

if ($studentId < 1) {
    http_response_code(403);
    exit('Access denied.');
}

$submittedToken = $_POST['csrf_token'] ?? null;
$sessionToken = $_SESSION['csrf_token'] ?? null;

if (
    !is_string($submittedToken)
    || !is_string($sessionToken)
    || $sessionToken === ''
    || !hash_equals($sessionToken, $submittedToken)
) {
    redirectToPermit('invalid_token');
}

$paymentType = $_POST['payment_type'] ?? null;
$period = $_POST['period'] ?? null;

if ($paymentType === 'full') {
    $period = null;
} elseif ($paymentType !== 'period') {
    redirectToPermit('invalid_request');
} elseif (!in_array($period, ['P1', 'P2', 'P3'], true)) {
    redirectToPermit('invalid_period');
}

/*
|--------------------------------------------------------------------------
| VALIDATE UPLOADED DOCUMENT
|--------------------------------------------------------------------------
*/

$file = $_FILES['permit_file'] ?? null;

if (!is_array($file)) {
    redirectToPermit('no_file');
}

$uploadError = $file['error'] ?? UPLOAD_ERR_NO_FILE;

if ($uploadError === UPLOAD_ERR_NO_FILE) {
    redirectToPermit('no_file');
}

if (in_array($uploadError, [UPLOAD_ERR_INI_SIZE, UPLOAD_ERR_FORM_SIZE], true)) {
    redirectToPermit('file_too_large');
}

if ($uploadError !== UPLOAD_ERR_OK) {
    redirectToPermit('upload_failed');
}

$tmpName = $file['tmp_name'] ?? null;

if (!is_string($tmpName) || !is_uploaded_file($tmpName) || !is_readable($tmpName)) {
    redirectToPermit('upload_failed');
}

$fileSize = filesize($tmpName);

if ($fileSize === false || $fileSize < 1) {
    redirectToPermit('invalid_file');
}

if ($fileSize > 5 * 1024 * 1024) {
    redirectToPermit('file_too_large');
}

$uploadDirectory = dirname(__DIR__, 2) . '/storage/permits';
$newFileMoved = false;
$commitStarted = false;
$storedFilename = '';
$previousStoredFilename = null;

try {
    $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    $allowedTypes = [
        'application/pdf' => 'pdf',
        'image/jpeg' => 'jpg',
        'image/png' => 'png',
    ];

    $finfo = new finfo(FILEINFO_MIME_TYPE);
    $mimeType = $finfo->file($tmpName);

    if (!is_string($mimeType) || !isset($allowedTypes[$mimeType])) {
        throw new DomainException('invalid_file');
    }

    $extension = $allowedTypes[$mimeType];

    $clientFilename = $file['name'] ?? '';
    $originalFilename = is_string($clientFilename)
        ? basename(str_replace('\\', '/', $clientFilename))
        : '';

    $originalFilename = trim(
        preg_replace('/[\x00-\x1F\x7F]/u', '', $originalFilename) ?? ''
    );

    if ($originalFilename === '') {
        $originalFilename = 'permit-document.' . $extension;
    }

    // The database column accepts 255 characters. Preserve UTF-8 characters.
    if (preg_match('/\A.{1,255}/us', $originalFilename, $matches)) {
        $originalFilename = $matches[0];
    }

    if (
        !is_dir($uploadDirectory)
        && !@mkdir($uploadDirectory, 0750, true)
        && !is_dir($uploadDirectory)
    ) {
        throw new RuntimeException('Cannot create the permit storage directory.');
    }

    if (!is_writable($uploadDirectory)) {
        throw new RuntimeException('Permit storage is not writable.');
    }

    $storedFilename = bin2hex(random_bytes(24)) . '.' . $extension;
    $destination = $uploadDirectory . '/' . $storedFilename;

    /*
    |--------------------------------------------------------------------------
    | LOCK THE STUDENT AND VERIFY OFFICIAL ENROLLMENT
    |--------------------------------------------------------------------------
    */

    $pdo->beginTransaction();

    // This row exists even before the student's first permit submission.
    $studentCheck = $pdo->prepare(
        "SELECT id
         FROM users
         WHERE id = ?
           AND role = 'student'
           AND is_active = 1
         FOR UPDATE"
    );
    $studentCheck->execute([$studentId]);

    if ($studentCheck->fetchColumn() === false) {
        throw new DomainException('invalid_request');
    }

    $enrollmentCheck = $pdo->prepare(
        "SELECT ss.section_id
         FROM section_students ss
         INNER JOIN sections s ON s.id = ss.section_id
         WHERE ss.student_id = ?
         LIMIT 1
         FOR UPDATE"
    );
    $enrollmentCheck->execute([$studentId]);

    if ($enrollmentCheck->fetchColumn() === false) {
        throw new DomainException('no_section');
    }

    /*
    |--------------------------------------------------------------------------
    | CHECK OVERLAPPING PAYMENTS AND FIND THE REJECTED ROW TO REUSE
    |--------------------------------------------------------------------------
    |
    | Incoming P1/P2/P3: check that period and any full payment.
    | Incoming full:     check every submission for the student.
    |
    | Reuse only an exact rejected match: P1 replaces P1, full replaces full.
    */

    $submissionCheck = $pdo->prepare(
        "SELECT id, payment_type, period, approval_status, stored_filename
         FROM permit_submissions
         WHERE student_id = ?
           AND (
               ? = 'full'
               OR payment_type = 'full'
               OR (payment_type = 'period' AND period = ?)
           )
         ORDER BY uploaded_at DESC, id DESC
         FOR UPDATE"
    );
    $submissionCheck->execute([$studentId, $paymentType, $period]);

    $rejectedSubmission = null;

    foreach ($submissionCheck->fetchAll(PDO::FETCH_ASSOC) as $submission) {
        if (in_array($submission['approval_status'], ['pending', 'approved'], true)) {
            throw new DomainException('duplicate_submission');
        }

        if (
            $rejectedSubmission === null
            && $submission['approval_status'] === 'rejected'
            && $submission['payment_type'] === $paymentType
            && $submission['period'] === $period
        ) {
            $rejectedSubmission = $submission;
        }
    }

    /*
    |--------------------------------------------------------------------------
    | STORE THE NEW FILE AND SAVE THE SUBMISSION
    |--------------------------------------------------------------------------
    */

    if (!move_uploaded_file($tmpName, $destination)) {
        throw new DomainException('upload_failed');
    }

    $newFileMoved = true;

    if ($rejectedSubmission !== null) {
        $replace = $pdo->prepare(
            "UPDATE permit_submissions
             SET stored_filename = ?,
                 original_filename = ?,
                 uploaded_at = CURRENT_TIMESTAMP,
                 approval_status = 'pending',
                 reviewed_by = NULL,
                 reviewed_at = NULL,
                 review_note = NULL
             WHERE id = ?
               AND student_id = ?
               AND approval_status = 'rejected'"
        );

        $replace->execute([
            $storedFilename,
            $originalFilename,
            $rejectedSubmission['id'],
            $studentId,
        ]);

        if ($replace->rowCount() !== 1) {
            throw new RuntimeException('The rejected submission could not be replaced.');
        }

        $previousStoredFilename = (string) $rejectedSubmission['stored_filename'];
    } else {
        $insert = $pdo->prepare(
            "INSERT INTO permit_submissions (
                student_id,
                payment_type,
                period,
                stored_filename,
                original_filename,
                uploaded_at,
                approval_status
             ) VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP, 'pending')"
        );

        $insert->execute([
            $studentId,
            $paymentType,
            $period,
            $storedFilename,
            $originalFilename,
        ]);
    }

    // If the connection fails during COMMIT, its outcome may be unknown.
    // In that case keep the new file because the database may reference it.
    $commitStarted = true;
    $pdo->commit();

} catch (Throwable $error) {
    $safeToRemoveNewFile = !$commitStarted;

    try {
        if ($pdo->inTransaction()) {
            $pdo->rollBack();
            $safeToRemoveNewFile = true;
        }
    } catch (Throwable $rollbackError) {
        error_log('AcadTrack permit rollback error: ' . $rollbackError->getMessage());
    }

    if ($newFileMoved && $safeToRemoveNewFile) {
        removeStoredPermitFile($uploadDirectory, $storedFilename);
    }

    if ($error instanceof DomainException) {
        redirectToPermit($error->getMessage());
    }

    error_log('AcadTrack permit upload error: ' . $error->getMessage());
    redirectToPermit('server_error');
}

/*
|--------------------------------------------------------------------------
| CLEAN UP THE REPLACED FILE AFTER A SUCCESSFUL COMMIT
|--------------------------------------------------------------------------
*/

if ($previousStoredFilename !== null && $previousStoredFilename !== $storedFilename) {
    try {
        // Older records may share a filename. Keep it if any row still uses it.
        $referenceCheck = $pdo->prepare(
            "SELECT 1
             FROM permit_submissions
             WHERE stored_filename = ?
             LIMIT 1"
        );
        $referenceCheck->execute([$previousStoredFilename]);

        if ($referenceCheck->fetchColumn() === false) {
            removeStoredPermitFile($uploadDirectory, $previousStoredFilename);
        }
    } catch (Throwable $cleanupError) {
        // The submission is already saved. File cleanup is a separate operation.
        error_log('AcadTrack old permit file cleanup: ' . $cleanupError->getMessage());
    }
}

$_SESSION['flash_success'] = $previousStoredFilename !== null
    ? 'Your rejected receipt was replaced and is awaiting SSP adviser review.'
    : 'Document uploaded successfully. Awaiting SSP adviser review.';

redirectToPermit();